-- dbt_inventory/models/marts/core/fct_inventory_daily.sql
CREATE OR REPLACE TABLE INVENTORY_360_DB.MARTS.FCT_INVENTORY_DAILY CLUSTER BY (snapshot_date) AS
-- Grain: one row per site x SKU x day. Joins the WMS stock position with
-- demand / sales so that availability and cover can be computed consistently.
select
    k.snapshot_date,
    k.warehouse_code,
    k.sku,
    p.category,
    p.velocity_class,
    k.qty_on_hand,
    k.qty_available,
    k.qty_received,
    k.qty_damaged,
    coalesce(s.units_demanded, 0)                      as units_demanded,
    coalesce(s.units_sold, 0)                          as units_sold,
    coalesce(s.units_lost, 0)                          as units_lost,
    coalesce(s.net_sales_gbp, 0)                       as net_sales_gbp,
    coalesce(s.units_sold, 0) * p.unit_cost_gbp        as cogs_gbp,
    coalesce(s.units_lost, 0) * p.unit_price_gbp       as lost_sales_gbp,
    k.qty_on_hand * p.unit_cost_gbp                    as stock_value_gbp,
    k.qty_on_hand * p.unit_price_gbp                   as stock_retail_value_gbp,
    ceil(k.qty_on_hand / nullif(p.units_per_pallet, 0)) as pallets_on_hand,
    k.qty_on_hand = 0                                  as is_out_of_stock
from INVENTORY_360_DB.STAGING.STG_STOCK_SNAPSHOTS k
join INVENTORY_360_DB.MARTS.DIM_PRODUCT p on p.sku = k.sku
left join INVENTORY_360_DB.STAGING.STG_SALES s
    on s.sales_date = k.snapshot_date
   and s.warehouse_code = k.warehouse_code
   and s.sku = k.sku;

-- dbt_inventory/models/staging/stg_purchase_order_lines.sql
CREATE OR REPLACE VIEW INVENTORY_360_DB.STAGING.STG_PURCHASE_ORDER_LINES AS
select
    po_number || '-' || lpad(to_varchar(po_line), 3, '0')      as po_line_id,
    po_number,
    po_line,
    supplier_id,
    warehouse_code,
    sku,
    order_date,
    expected_date,
    received_date,
    qty_ordered,
    qty_received,
    unit_cost_gbp,
    qty_ordered * unit_cost_gbp                                as order_value_gbp,
    upper(po_status)                                           as po_status,
    datediff(day, expected_date, received_date)                as days_late,
    received_date is not null and received_date <= expected_date as is_on_time,
    received_date is not null and qty_received >= qty_ordered  as is_in_full
from INVENTORY_360_DB.RAW.ERP_PURCHASE_ORDER_LINES;

-- dbt_inventory/models/marts/core/fct_purchase_orders.sql
CREATE OR REPLACE TABLE INVENTORY_360_DB.MARTS.FCT_PURCHASE_ORDERS AS
select
    l.*,
    p.category,
    p.product_name,
    s.supplier_name,
    s.sourcing_region,
    s.lead_time_days                                    as contract_lead_time_days,
    datediff(day, l.order_date, l.received_date)        as actual_lead_time_days,
    l.qty_received * l.unit_cost_gbp                    as received_value_gbp,
    case when l.po_status = 'RECEIVED' then (l.is_on_time and l.is_in_full) end as is_otif
from INVENTORY_360_DB.STAGING.STG_PURCHASE_ORDER_LINES l
join INVENTORY_360_DB.MARTS.DIM_PRODUCT p on p.sku = l.sku
join INVENTORY_360_DB.MARTS.DIM_SUPPLIER s on s.supplier_id = l.supplier_id;

