-- dbt_inventory/models/marts/core/fct_shipments.sql
CREATE OR REPLACE TABLE INVENTORY_360_DB.MARTS.FCT_SHIPMENTS AS
select
    sh.*,
    s.supplier_id,
    s.supplier_name,
    s.sourcing_region,
    (sh.freight_cost_gbp) / NULLIF((sh.pallets), 0)       as freight_cost_per_pallet_gbp,
