-- dbt_inventory/models/marts/reporting/rpt_budget_vs_actual.sql
CREATE OR REPLACE TABLE INVENTORY_360_DB.MARTS.RPT_BUDGET_VS_ACTUAL AS
-- Grain: month x budget area x dimension (category or site).
-- Actuals are sourced from the same facts that drive operational reporting
-- so finance and operations reconcile.
with actuals as (
    select date_trunc('month', order_date) as period_month,
           'Inventory Purchases'           as budget_area,
           category                        as dimension_key,
           sum(order_value_gbp)            as actual_gbp
    from INVENTORY_360_DB.MARTS.FCT_PURCHASE_ORDERS
    group by 1, 2, 3
    union all
    select date_trunc('month', planned_arrival), 'Freight & Duty', warehouse_code, sum(landed_cost_gbp)
    from INVENTORY_360_DB.MARTS.FCT_SHIPMENTS
    group by 1, 2, 3
    union all
    select period_month, 'Warehousing', warehouse_code, sum(actual_cost_gbp)
    from INVENTORY_360_DB.STAGING.STG_WAREHOUSE_COSTS
    group by 1, 2, 3
),
closed as (
    -- Only fully closed months count as actuals
    select * from actuals where period_month < date_trunc('month', current_date())
)
select
    b.period_month,
    b.fiscal_year,
    b.budget_area,
    b.dimension_key,
    b.budget_version,
    b.budget_gbp,
    a.actual_gbp,
    b.forecast_gbp,
    coalesce(a.actual_gbp, b.forecast_gbp)                             as outturn_gbp,
    a.actual_gbp - b.budget_gbp                                        as variance_gbp,
    (a.actual_gbp - b.budget_gbp) / NULLIF((b.budget_gbp), 0)   as variance_pct,
    a.actual_gbp is not null                                           as is_actualised
from INVENTORY_360_DB.STAGING.STG_BUDGETS b
left join closed a
    on a.period_month = b.period_month
   and a.budget_area = b.budget_area
   and a.dimension_key = b.dimension_key;

-- dbt_inventory/models/marts/reporting/rpt_inventory_kpis_monthly.sql
CREATE OR REPLACE TABLE INVENTORY_360_DB.MARTS.RPT_INVENTORY_KPIS_MONTHLY AS
-- Grain: month x site x category. Core inventory health KPIs.
with daily as (
    select
        date_trunc('month', snapshot_date)                 as period_month,
        warehouse_code,
        category,
        snapshot_date,
        sum(stock_value_gbp)                               as stock_value_gbp,
        sum(units_demanded)                                as units_demanded,
        sum(units_sold)                                    as units_sold,
        sum(net_sales_gbp)                                 as net_sales_gbp,
        sum(cogs_gbp)                                      as cogs_gbp,
        sum(lost_sales_gbp)                                as lost_sales_gbp,
        count(*)                                           as sku_locations,
        sum(iff(is_out_of_stock, 1, 0))                    as sku_locations_oos
    from INVENTORY_360_DB.MARTS.FCT_INVENTORY_DAILY
    group by 1, 2, 3, 4
)
select
    period_month,
    'FY' || RIGHT(TO_VARCHAR(YEAR(DATEADD(month, -3, period_month))), 2)
         || '/' || RIGHT(TO_VARCHAR(YEAR(DATEADD(month, -3, period_month)) + 1), 2)                   as fiscal_year,
    warehouse_code,
    category,
    count(distinct snapshot_date)                          as trading_days,
    avg(stock_value_gbp)                                   as avg_stock_value_gbp,
    max_by(stock_value_gbp, snapshot_date)                 as closing_stock_value_gbp,
    sum(units_demanded)                                    as units_demanded,
    sum(units_sold)                                        as units_sold,
    sum(net_sales_gbp)                                     as net_sales_gbp,
    sum(cogs_gbp)                                          as cogs_gbp,
    sum(net_sales_gbp) - sum(cogs_gbp)                     as gross_profit_gbp,
    sum(lost_sales_gbp)                                    as lost_sales_gbp,
    (sum(units_sold)) / NULLIF((sum(units_demanded)), 0)        as fill_rate,
    (sum(sku_locations_oos)) / NULLIF((sum(sku_locations)), 0) as oos_rate,
    -- Annualised stock turn and days inventory outstanding
    (sum(cogs_gbp) * 365 / count(distinct snapshot_date)) / NULLIF((avg(stock_value_gbp)), 0) as stock_turns_annualised,
    (avg(stock_value_gbp) * count(distinct snapshot_date)) / NULLIF((sum(cogs_gbp)), 0)      as days_inventory_outstanding,
    avg(stock_value_gbp) * 0.22 / 12                                      as holding_cost_gbp
from daily
group by 1, 2, 3, 4;

-- dbt_inventory/models/marts/reporting/rpt_inventory_position.sql
CREATE OR REPLACE TABLE INVENTORY_360_DB.MARTS.RPT_INVENTORY_POSITION AS
-- Grain: one row per site x SKU for the latest snapshot date.
-- Implements a periodic-review (R, s, S) replenishment policy:
--   safety stock   = z(service level) * sigma(daily demand) * sqrt(lead time)
--   reorder point  = mean daily demand * lead time + safety stock
--   order-up-to    = reorder point + mean daily demand * review period
--   inventory pos. = on hand - allocated + open / in-transit purchase orders
with latest as (
    select max(snapshot_date) as as_of_date from INVENTORY_360_DB.MARTS.FCT_INVENTORY_DAILY
),

demand as (
    select
        f.warehouse_code,
        f.sku,
        avg(f.units_demanded)              as avg_daily_demand,
        stddev_samp(f.units_demanded)      as stddev_daily_demand,
        sum(f.units_sold)                  as units_sold_28d,
        sum(f.net_sales_gbp)               as net_sales_28d_gbp,
        sum(f.lost_sales_gbp)              as lost_sales_28d_gbp,
        avg(iff(f.is_out_of_stock, 1, 0))  as oos_rate_28d
    from INVENTORY_360_DB.MARTS.FCT_INVENTORY_DAILY f, latest
    where f.snapshot_date > dateadd(day, -28, latest.as_of_date)
    group by 1, 2
),

inbound as (
    select
        warehouse_code,
        sku,
        sum(qty_ordered)                   as inbound_qty,
        min(expected_date)                 as next_delivery_date,
        count(distinct po_number)          as open_po_count
    from INVENTORY_360_DB.MARTS.FCT_PURCHASE_ORDERS
    where po_status in ('OPEN', 'IN_TRANSIT')
    group by 1, 2
),

current_stock as (
    select f.*
    from INVENTORY_360_DB.MARTS.FCT_INVENTORY_DAILY f
    join latest on f.snapshot_date = latest.as_of_date
),

base as (
    select
        c.snapshot_date                                         as as_of_date,
        c.warehouse_code,
        w.warehouse_name,
        w.uk_region,
        c.sku,
        p.product_name,
        p.category,
        p.subcategory,
        p.brand,
        p.supplier_id,
        p.supplier_name,
        p.sourcing_region,
        p.velocity_class,
        p.lifecycle_status,
        p.unit_cost_gbp,
        p.unit_price_gbp,
        p.min_order_qty,
        p.units_per_pallet,
        p.supplier_lead_time_days                               as lead_time_days,
        case p.velocity_class when 'A' then 7 when 'B' then 14 else 28 end as review_period_days,
        case p.velocity_class when 'A' then 1.65 when 'B' then 1.28 else 1.04 end as service_z,
        case p.velocity_class when 'A' then 0.95 when 'B' then 0.90 else 0.85 end as target_service_level,
        c.qty_on_hand,
        c.qty_available,
        c.qty_on_hand - c.qty_available                         as qty_allocated,
        c.stock_value_gbp,
        c.stock_retail_value_gbp,
        c.pallets_on_hand,
        coalesce(d.avg_daily_demand, 0)                         as avg_daily_demand,
        coalesce(d.stddev_daily_demand, 0)                      as stddev_daily_demand,
        coalesce(d.units_sold_28d, 0)                           as units_sold_28d,
        coalesce(d.net_sales_28d_gbp, 0)                        as net_sales_28d_gbp,
        coalesce(d.lost_sales_28d_gbp, 0)                       as lost_sales_28d_gbp,
        coalesce(d.oos_rate_28d, 0)                             as oos_rate_28d,
        coalesce(i.inbound_qty, 0)                              as inbound_qty,
        i.next_delivery_date,
        coalesce(i.open_po_count, 0)                            as open_po_count
    from current_stock c
    join INVENTORY_360_DB.MARTS.DIM_PRODUCT p   on p.sku = c.sku
    join INVENTORY_360_DB.MARTS.DIM_WAREHOUSE w on w.warehouse_code = c.warehouse_code
    left join demand d  on d.warehouse_code = c.warehouse_code and d.sku = c.sku
    left join inbound i on i.warehouse_code = c.warehouse_code and i.sku = c.sku
),

policy as (
    select
        base.*,
        ceil(service_z * stddev_daily_demand * sqrt(lead_time_days))            as safety_stock_qty,
        ceil(avg_daily_demand * lead_time_days
             + service_z * stddev_daily_demand * sqrt(lead_time_days))          as reorder_point_qty,
        ceil(avg_daily_demand * (lead_time_days + review_period_days)
             + service_z * stddev_daily_demand * sqrt(lead_time_days))          as order_up_to_qty,
        qty_on_hand - qty_allocated + inbound_qty                               as inventory_position_qty,
        (qty_on_hand) / NULLIF((avg_daily_demand), 0)                    as days_of_cover
    from base
),

classified as (
    select
        policy.*,
        case
            when qty_on_hand = 0 and avg_daily_demand > 0                               then 'Out of stock'
            when avg_daily_demand = 0 and qty_on_hand > 0                               then 'Excess'
            when days_of_cover < 3                       then 'Critical'
            when days_of_cover < 7                            then 'Low'
            when days_of_cover > 120                         then 'Excess'
            when days_of_cover > 60                      then 'Overstock'
            else 'Healthy'
        end                                                                             as stock_status,
        iff(inventory_position_qty < reorder_point_qty and lifecycle_status <> 'Discontinued',
            ceil((order_up_to_qty - inventory_position_qty) / nullif(min_order_qty, 0)) * min_order_qty,
            0)                                                                          as recommended_order_qty,
        greatest(qty_on_hand - avg_daily_demand * 60, 0) * unit_cost_gbp
                                                                                        as excess_stock_value_gbp
    from policy
)

select
    classified.*,
    recommended_order_qty * unit_cost_gbp                                               as recommended_order_value_gbp,
    ceil(recommended_order_qty / nullif(units_per_pallet, 0))                           as recommended_pallets,
    case
        when recommended_order_qty = 0                                                  then 'None'
        when stock_status in ('Out of stock', 'Critical') and velocity_class = 'A'      then 'P1 - Urgent'
        when stock_status in ('Out of stock', 'Critical')                               then 'P2 - High'
        when stock_status = 'Low'                                                       then 'P3 - Medium'
        else 'P4 - Routine'
    end                                                                                 as replenishment_priority,
    dateadd(day, lead_time_days, as_of_date)                                            as earliest_arrival_if_ordered
from classified;

-- dbt_inventory/models/marts/reporting/rpt_logistics_monthly.sql
CREATE OR REPLACE TABLE INVENTORY_360_DB.MARTS.RPT_LOGISTICS_MONTHLY AS
-- Grain: month (planned arrival) x transport mode x carrier x destination site
select
    date_trunc('month', planned_arrival)                               as period_month,
    'FY' || RIGHT(TO_VARCHAR(YEAR(DATEADD(month, -3, date_trunc('month', planned_arrival)))), 2)
         || '/' || RIGHT(TO_VARCHAR(YEAR(DATEADD(month, -3, date_trunc('month', planned_arrival))) + 1), 2)       as fiscal_year,
    transport_mode,
    carrier,
    warehouse_code,
    sourcing_region,
    count(*)                                                           as shipments,
    sum(iff(shipment_status = 'DELIVERED', 1, 0))                      as shipments_delivered,
    sum(iff(shipment_status = 'IN_TRANSIT', 1, 0))                     as shipments_in_transit,
    sum(pallets)                                                       as pallets,
    sum(freight_cost_gbp)                                              as freight_cost_gbp,
    sum(duty_cost_gbp)                                                 as duty_cost_gbp,
    sum(landed_cost_gbp)                                               as landed_cost_gbp,
    (sum(freight_cost_gbp)) / NULLIF((sum(pallets)), 0)         as freight_cost_per_pallet_gbp,
    avg(iff(is_on_time_arrival, 1, 0))                                 as on_time_arrival_rate,
    avg(iff(shipment_status = 'DELIVERED', greatest(arrival_delay_days, 0), null)) as avg_delay_days,
    avg(transit_days)                                                  as avg_transit_days,
    sum(co2_kg) / 1000                                                 as co2_tonnes
from INVENTORY_360_DB.MARTS.FCT_SHIPMENTS
group by 1, 2, 3, 4, 5, 6;

-- dbt_inventory/models/marts/reporting/rpt_supplier_scorecard.sql
CREATE OR REPLACE TABLE INVENTORY_360_DB.MARTS.RPT_SUPPLIER_SCORECARD AS
-- Grain: one row per supplier. Rolling 12-month performance scorecard.
with po as (
    select *
    from INVENTORY_360_DB.MARTS.FCT_PURCHASE_ORDERS
    where order_date >= dateadd(month, -12, current_date())
),
perf as (
    select
        supplier_id,
        count(distinct po_number)                                       as po_count,
        count(*)                                                        as po_lines,
        sum(order_value_gbp)                                            as spend_gbp,
        sum(iff(po_status = 'RECEIVED', 1, 0))                          as lines_received,
        avg(iff(po_status = 'RECEIVED', iff(is_on_time, 1, 0), null))   as on_time_rate,
        avg(iff(po_status = 'RECEIVED', iff(is_in_full, 1, 0), null))   as in_full_rate,
        avg(iff(is_otif, 1, 0))                                         as otif_rate,
        (sum(iff(po_status = 'RECEIVED', qty_received, 0))) / NULLIF((sum(iff(po_status = 'RECEIVED', qty_ordered, 0))), 0) as unit_fill_rate,
        avg(iff(po_status = 'RECEIVED', greatest(days_late, 0), null))  as avg_days_late,
        avg(actual_lead_time_days)                                      as avg_actual_lead_time_days,
        stddev_samp(actual_lead_time_days)                              as lead_time_variability_days,
        sum(iff(po_status in ('OPEN', 'IN_TRANSIT'), order_value_gbp, 0)) as open_order_value_gbp
    from po
    group by 1
),
freight as (
    select supplier_id,
           sum(freight_cost_gbp)  as freight_cost_gbp,
           sum(duty_cost_gbp)     as duty_cost_gbp,
           sum(co2_kg) / 1000     as co2_tonnes
    from INVENTORY_360_DB.MARTS.FCT_SHIPMENTS
    where dispatch_date >= dateadd(month, -12, current_date())
    group by 1
),
scored as (
    select
        s.supplier_id,
        s.supplier_name,
        s.country_code,
        s.country_name,
        s.sourcing_region,
        s.primary_category,
        s.contract_tier,
        s.lead_time_days                                                as contract_lead_time_days,
        s.payment_terms_days,
        p.po_count,
        p.po_lines,
        p.spend_gbp,
        p.open_order_value_gbp,
        p.on_time_rate,
        p.in_full_rate,
        p.otif_rate,
        p.unit_fill_rate,
        p.avg_days_late,
        p.avg_actual_lead_time_days,
        p.lead_time_variability_days,
        f.freight_cost_gbp,
        f.duty_cost_gbp,
        f.co2_tonnes,
        (f.freight_cost_gbp + f.duty_cost_gbp) / NULLIF((p.spend_gbp), 0) as landed_cost_uplift_pct,
        -- Weighted composite score (0-100): OTIF 50%, fill 25%, lead-time stability 15%, cost 10%
        round(100 * (
              0.50 * coalesce(p.otif_rate, 0)
            + 0.25 * coalesce(p.unit_fill_rate, 0)
            + 0.15 * greatest(0, 1 - coalesce(p.lead_time_variability_days, 0) / 15)
            + 0.10 * greatest(0, 1 - coalesce((f.freight_cost_gbp + f.duty_cost_gbp) / NULLIF((p.spend_gbp), 0), 0) / 0.30)
        ), 1)                                                           as performance_score
    from INVENTORY_360_DB.MARTS.DIM_SUPPLIER s
    left join perf p    on p.supplier_id = s.supplier_id
    left join freight f on f.supplier_id = s.supplier_id
)
select
    scored.*,
    case when performance_score >= 85 then 'Low'
         when performance_score >= 72 then 'Medium'
         else 'High' end                                                as risk_rating,
    rank() over (order by spend_gbp desc)                               as spend_rank
from scored;

-- dbt_inventory/models/marts/reporting/rpt_warehouse_utilisation.sql
CREATE OR REPLACE TABLE INVENTORY_360_DB.MARTS.RPT_WAREHOUSE_UTILISATION AS
-- Grain: month x site. Capacity utilisation and operating cost efficiency.
with occupancy as (
    select
        date_trunc('month', snapshot_date)                 as period_month,
        warehouse_code,
        snapshot_date,
        sum(pallets_on_hand)                               as pallets_used,
        sum(units_sold)                                    as units_dispatched,
        sum(qty_received)                                  as units_received,
        sum(stock_value_gbp)                               as stock_value_gbp
    from INVENTORY_360_DB.MARTS.FCT_INVENTORY_DAILY
    group by 1, 2, 3
),
monthly as (
    select
        period_month,
        warehouse_code,
        avg(pallets_used)                                  as avg_pallets_used,
        max(pallets_used)                                  as peak_pallets_used,
        sum(units_dispatched)                              as units_dispatched,
        sum(units_received)                                as units_received,
        avg(stock_value_gbp)                               as avg_stock_value_gbp
    from occupancy
    group by 1, 2
),
costs as (
    select period_month, warehouse_code,
           sum(actual_cost_gbp)                                         as opex_gbp,
           sum(iff(cost_category = 'Labour', actual_cost_gbp, 0))       as labour_cost_gbp
    from INVENTORY_360_DB.STAGING.STG_WAREHOUSE_COSTS
    group by 1, 2
)
select
    m.period_month,
    m.warehouse_code,
    w.warehouse_name,
    w.uk_region,
    w.nation,
    w.site_type,
    w.capacity_pallets,
    w.latitude,
    w.longitude,
    m.avg_pallets_used,
    m.peak_pallets_used,
    (m.avg_pallets_used) / NULLIF((w.capacity_pallets), 0)      as avg_utilisation_pct,
    (m.peak_pallets_used) / NULLIF((w.capacity_pallets), 0)     as peak_utilisation_pct,
    m.units_dispatched,
    m.units_received,
    m.avg_stock_value_gbp,
    c.opex_gbp,
    c.labour_cost_gbp,
    (c.opex_gbp) / NULLIF((m.units_dispatched), 0)              as cost_per_unit_dispatched_gbp,
    (c.opex_gbp) / NULLIF((m.avg_pallets_used), 0)              as cost_per_pallet_stored_gbp
from monthly m
join INVENTORY_360_DB.MARTS.DIM_WAREHOUSE w on w.warehouse_code = m.warehouse_code
left join costs c on c.period_month = m.period_month and c.warehouse_code = m.warehouse_code;
